CREATE     VIEW [FO].[vwCustTransOpen] 
AS
SELECT 
	cto.RECID
	,cto.ACCOUNTNUM
	,cto.AMOUNTCUR
	,cto.AMOUNTMST
	,cto.BANKDISCNOTICEDEADLINE
	,cto.CASHDISCDATE
	,cto.DUEDATE
	,cto.EXCHADJUNREALIZED
	,cto.EXCHADJUNREALIZEDREPORTING
	,cto.FINEAMOUNT_BR
	,cto.FINEAMOUNTPAYMCUR_BR
	,cto.FINECODE_BR
	,cto.INTERESTAMOUNT_BR
	,cto.INTERESTAMOUNTPAYMCUR_BR
	,cto.INTERESTCODE_BR
	,cto.LASTINTERESTDATE
	,cto.POSSIBLECASHDISC
	,cto.REPORTINGCURRENCYAMOUNT
	,cto.SETTLEDLINEPERCENT_IN
	,cto.SETTLEDTOTALAMOUNT_IN
	,cto.SETTLEMENTPRIORITYCASHDISCDATE
	,cto.TAXWITHHOLDAMOUNTORIGIN_IN
	,cto.TCSAMOUNT_IN
	,cto.TDSAMOUNT_IN
	,cto.TRANSDATE
	,cto.USECASHDISC
	,cto.COLLECTIONLETTER
	,cto.COLLECTIONLETTERCODE
	,cto.COVSTATUS
	,cto.TAXDISTRIBUTION
	,T2.DISPLAYVALUE AS CASHDISCOUNTLEDGERDIMENSIONDISPLAYVALUE
	,cto.REFRECID
	--,cto.SKS_EPY_SENTTOEPAY
	,cto.DATAAREAID

FROM [synapse_fo].[CustTransOpen] cto
LEFT OUTER JOIN [synapse_fo].[DIMENSIONCOMBINATIONENTITY_RICS] T2 ON (
		(cto.CASHDISCOUNTLEDGERDIMENSION = T2.RECID)
		AND (cto.PARTITION = T2.PARTITION)
		)
